"""Fixed-draft, program-enumerated review experiment. No production workflow change."""
from pathlib import Path
from copy import deepcopy
import hashlib,json,sys,time
ROOT=Path('C:/Users/34994/Desktop/seekra')
sys.path.insert(0,str(ROOT/'tests'))
import httpx
from test_documents import add_page
from test_research import deliver
from seekra.answers import compile_answer
from seekra.cli import read_config
from seekra.models import DeepSeekModel
from seekra.runtime import CancellationToken
from seekra.session import Session
HERE=Path(__file__).parent
FIELDS={'judgments':('text','conditions'),'recommendations':('text',),'unknowns':('question','answer_impact')}
SYSTEM=('你是研究终稿的复核者。只根据给定的用户原问题和保存原文，核对完整 draft 中所有 target_paths，'
'逐项判断 keep/revise/uncertain，不自行筛选检查对象。只修正实质错误，不为风格改写。'
'核对对象、时点、适用条件、确定程度、方案依赖及来源归因。'
'允许忠实转述、合理场景推断和明确标注的保守建议，不能只因建议更早行动就判错。'
'缺少的机制不能暗中当作成立，调查未知的行动也不要求未知得到肯定答案。'
'检查同一事实在判断、条件、建议及标题中的一致性，避免只改一处。'
'原文和 evidence 不可修改。需要承认新的未知时可增加 unknowns，并明确修改相关建议的关联；'
'不引入给定资料以外的事实，不认证整份答案正确。'
'必须单独调用 submit_review。每个路径恰好一项；keep/uncertain 的 replacement 填空字符串，'
'revise 填该字段的完整替换文本。reason 用一句简短理由。'
'增加未知项时，序号按原 unknowns 长度顺序追加；可在 recommendation_links 中使用这些序号。'
'未提供的关联保持原样。关联更新只改指定建议的三个索引列表，不改变其正文；正文变化必须列在对应文本路径。')

def text_fields(draft):
 result=[]
 for group,fields in FIELDS.items():
  for i,row in enumerate(draft[group]):
   for field in fields:result.append('/'+group+'/'+str(i)+'/'+field)
 for i,node in enumerate(draft.get('layout',[])):
  if node['type']=='heading':result.append('/layout/'+str(i)+'/text')
 return result

def object_schema(properties):
 return {'type':'object','properties':properties,'required':list(properties),'additionalProperties':False}

def review_definition(paths):
 string={'type':'string'}
 indices={'type':'array','items':{'type':'integer','minimum':1},'maxItems':20}
 return {'type':'function','function':{'name':'submit_review','description':'提交全部指定字段的复核及局部修改；不是正确性认证。',
 'parameters':object_schema({
 'items':{'type':'array','minItems':len(paths),'maxItems':len(paths),'items':object_schema({
   'path':{'type':'string','enum':paths},'assessment':{'type':'string','enum':['keep','revise','uncertain']},
   'reason':{'type':'string','maxLength':180},'replacement':string})},
 'added_unknowns':{'type':'array','maxItems':5,'items':object_schema({'question':string,'answer_impact':string})},
 'recommendation_links':{'type':'array','maxItems':10,'items':object_schema({
    'index':{'type':'integer','minimum':1},'judgment_indices':indices,'unknown_indices':indices,'dependency_indices':indices})}
 })}}

def apply_review(draft,review,paths):
 if set(review)!={'items','added_unknowns','recommendation_links'}:raise ValueError('Invalid review fields')
 items=review['items']
 if not isinstance(items,list) or len(items)!=len(paths):raise ValueError('Review coverage count mismatch')
 got=[item.get('path') for item in items]
 if set(got)!=set(paths) or len(set(got))!=len(got):raise ValueError('Missing, duplicate or unknown text paths')
 revised=deepcopy(draft)
 for item in items:
  if set(item)!={'path','assessment','reason','replacement'}:raise ValueError('Invalid review item')
  if not isinstance(item['reason'],str) or not item['reason'].strip():raise ValueError('Missing reason')
  assessment=item['assessment'];replacement=item['replacement']
  if assessment not in {'keep','revise','uncertain'} or not isinstance(replacement,str):raise ValueError('Invalid assessment')
  if assessment!='revise':
   if replacement:raise ValueError('Unrequested replacement on keep/uncertain')
   continue
  group,index,field=item['path'].strip('/').split('/')
  revised[group][int(index)][field]=replacement
 added=review['added_unknowns']
 if not isinstance(added,list) or len(added)>5:raise ValueError('Invalid added unknowns')
 first=len(revised['unknowns'])+1
 revised['unknowns'].extend(deepcopy(added))
 linked=set();changed=set()
 for change in review['recommendation_links']:
  if set(change)!={'index','judgment_indices','unknown_indices','dependency_indices'}:raise ValueError('Invalid link update')
  index=change['index']
  if type(index) is not int or not 1<=index<=len(revised['recommendations']) or index in changed:
   raise ValueError('Duplicate or invalid recommendation')
  changed.add(index)
  revised['recommendations'][index-1].update({k:deepcopy(v) for k,v in change.items() if k!='index'})
 for rec in revised['recommendations']:linked.update(rec['unknown_indices'])
 if 'layout' in revised:
  for index in range(first,len(revised['unknowns'])+1):
   if index not in linked:revised['layout'].append({'type':'unknown','index':index})
 return revised

def final_draft(records):
 return [json.loads(r['result'])['draft'] for r in records if r.get('kind')=='tool_completed'
   and r.get('tool_name')=='submit_answer' and json.loads(r['result']).get('status')=='success'][-1]

def cases():
 recent=json.loads((ROOT/'evals/evidence/advice-dependencies-live-20261007.json').read_text(encoding='utf-8'))
 offline=next(r for r in recent['rows'] if r['case']=='offline')
 older=json.loads((ROOT/'evals/evidence/answer-loop-relay-20261005.json').read_text(encoding='utf-8'))
 pages=[(url,p) for r in older['records'] if r.get('kind')=='tool_completed'
    for url,p in r.get('page_updates',{}).items() if p]
 layout=json.loads((ROOT/'evals/evidence/answer-layout-live-20261007.json').read_text(encoding='utf-8'))
 partial=next(r for r in layout['rows'] if r['case']=='partial')
 result=[
 {'id':'existing_offline','question':offline['question'],'source':offline['source'],
  'url':'https://example.org/controlled/offline','draft':final_draft(offline['records']),
  'origin':'advice-dependencies-live-20261007.json / offline','evaluation_role':'existing_error'},
 {'id':'existing_operations','question':older['question'],'source':pages[-1][1]['content'],'url':pages[-1][0],
  'draft':final_draft(older['records']),'origin':'answer-loop-relay-20261005.json','evaluation_role':'existing_error'},
 {'id':'correct_partial','question':partial['question'],'source':partial['source'],
  'url':'https://example.org/controlled/partial','draft':final_draft(partial['records']),
  'origin':'answer-layout-live-20261007.json / partial','evaluation_role':'positive_control'}]
 source=offline['source']
 ref='S1-P1@0-'+str(len(source))
 correct={'evidence':[{'reference':ref,'quote':'The license must be validated online again after 30 consecutive days offline.'}],
 'judgments':[
  {'text':'共享访客账户不能使用离线模式。改用普通个人账户只排除了这一项禁用情形，不能因此保证方案可行。',
   'conditions':'其他离线条件仍须满足；本文没有确认所有其他账户均可使用离线模式。','evidence_indices':[1]},
  {'text':'原文要求连续离线30天后再次联网验证，没有给出必须提前到第30天之前完成验证的明确截止。',
   'conditions':'未规定提前验证与计时重置规则，也未规定超过触发点后未验证的具体后果。','evidence_indices':[1]}],
 'recommendations':[
  {'text':'建议尽早向维护方核实普通个人账户的离线资格、提前验证及计时重置规则；发起询问不依赖这些机制已经成立。',
   'judgment_indices':[1,2],'unknown_indices':[1,2],'dependency_indices':[]},
  {'text':'若确认提前验证会按预期重置计时，且所用账户的离线资格、许可和准备条件均满足，才可进一步考虑每28天验证的候选安排。28天是保守安排建议，文档没有要求这一间隔，也未保证该方案。',
   'judgment_indices':[1,2],'unknown_indices':[1,2],'dependency_indices':[1,2]}],
 'unknowns':[
  {'question':'提前验证是否可用，且是否会按预期重置离线计时？','answer_impact':'决定周期验证方案能否成立，不能在未确认前承诺其可行。'},
  {'question':'普通个人账户是否具有所需离线资格？','answer_impact':'排除共享访客这一禁用情形不等于确认其他账户具备全部资格。'}],
 'layout':[{'type':'heading','level':2,'text':'原文支持的结论'},{'type':'judgment','index':1},
  {'type':'judgment','index':2},{'type':'evidence','index':1},
  {'type':'heading','level':2,'text':'调查行动与候选安排'},{'type':'recommendation','index':1},{'type':'recommendation','index':2}]}
 result.append({'id':'correct_conservative','question':offline['question'],'source':source,
  'url':'https://example.org/controlled/offline','draft':correct,
  'origin':'Human-authored complete positive control grounded in evals/claim-boundaries.json',
  'evaluation_role':'positive_control'})
 return result

def main():
 config=read_config(ROOT/'.env');materials=cases();sessions={};packets={};definitions={}
 for case in materials:
  session=Session();page=add_page(session,case['source'],url=case['url']);deliver(session)
  case['original_compiled']=compile_answer(session,case['draft'])
  case['target_paths']=text_fields(case['draft']);sessions[case['id']]=session
  packets[case['id']]={'question':case['question'],'saved_source':{'url':case['url'],'content':case['source']},
    'draft':case['draft'],'target_paths':case['target_paths'],
    'allowed_changes':'全部文本字段逐项复核；evidence 固定。可增加未知并修改建议关联；无布局的新未知会在末尾显示，已关联的在建议旁显示。'}
  definitions[case['id']]=review_definition(case['target_paths'])
 rows=[]
 with httpx.Client(timeout=httpx.Timeout(120,connect=20)) as client:
  model=DeepSeekModel(client,config['DEEPSEEK_MODEL'],config['DEEPSEEK_API_KEY'],thinking=True,reasoning_effort='high',max_output_tokens=8192)
  for repeat in range(2):
   for case in (materials if repeat==0 else list(reversed(materials))):
    started=time.monotonic();usage=[];response=None;review=None;revised=None;compiled=None;error=None
    messages=[{'role':'system','content':SYSTEM},{'role':'user','content':json.dumps(packets[case['id']],ensure_ascii=False)}]
    try:
     response=model.generate(messages,[definitions[case['id']]],on_content=lambda text:None,on_usage=usage.append,cancel=CancellationToken())
     calls=response.message.get('tool_calls') or []
     if response.finish_reason!='tool_calls' or len(calls)!=1 or calls[0]['function']['name']!='submit_review':
      raise ValueError('Expected one review submission')
     review=json.loads(calls[0]['function']['arguments'])
     revised=apply_review(case['draft'],review,case['target_paths'])
     compiled=compile_answer(sessions[case['id']],revised)
    except Exception as exc:
     error={'type':type(exc).__name__,'detail':str(exc) if isinstance(exc,ValueError) else 'request_failed'}
    row={'case':case['id'],'repeat':repeat+1,'seconds':round(time.monotonic()-started,2),'usage':usage,
     'message':response.message if response else None,'provider':response.provider if response else None,
     'review':review,'revised_draft':revised,'compiled':compiled,'error':error}
    rows.append(row)
    (HERE/f'{case["id"]}-{repeat+1}.json').write_text(json.dumps(row,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({'case':case['id'],'repeat':repeat+1,'fields':len(case['target_paths']),
      'revised_fields':sum(x['assessment']=='revise' for x in review['items']) if review else None,
      'added_unknowns':len(review['added_unknowns']) if review else None,
      'compiled':compiled is not None,'seconds':row['seconds'],'error':error},ensure_ascii=False),flush=True)
 report={'date':'2026-10-07','purpose':'Program-enumerated full-field review of fixed complete drafts',
  'model':config['DEEPSEEK_MODEL'],'thinking':True,'reasoning_effort':'high','max_output_tokens':8192,
  'system':SYSTEM,'materials':materials,'packets':packets,'definitions':definitions,'rows':rows,
  'model_requests':len(rows),'live_tavily_calls':0,'production_modified':False,
  'limits':'Fixed drafts, one independent cold review call per trial; two repeats for each of four drafts. Two existing-error drafts, one existing partial-reading control, one human-authored conservative-advice control. Roles and expected outcomes are not in model input. No iterative review, no default integration, no search. Compiler uses synthetic source delivery. Handoff/long-task effects not tested.',
  'source_fingerprints':{str(p.relative_to(ROOT)).replace('\\','/'):hashlib.sha256(p.read_bytes()).hexdigest()
   for p in (ROOT/'src/seekra/answers.py',ROOT/'src/seekra/models.py')},
  'runner_source':Path(__file__).read_text(encoding='utf-8-sig')}
 encoded=json.dumps(report,ensure_ascii=False,indent=2)
 assert all(value not in encoded for key,value in config.items() if key.endswith('API_KEY'))
 (HERE/'report.json').write_text(encoded,encoding='utf-8');print('FINISHED',flush=True)
if __name__=='__main__':main()
